selected.compute:
options = read('/input/options')
ids = []
for record in options:
    ids = ids + [record['id']]
result = []
for choice in combinations(ids, 3):
    candidate = list(choice)
    if valid(candidate):
        result = candidate
        break

selected.effects:
if not exists('/output/selection'):
    write('/output/selection', result)
if receipt('report') == 'unattempted':
    send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')
